// The instructions and examples a person takes to a language model live in docs/release/content/ai-site-spec (the one place they are written and read on the docs
// site). The dashboard and the API serve them from src/site-spec-material.generated.ts, which this test writes (UPDATE_SITE_SPEC_SCHEMA=1 pnpm test)
// and otherwise checks: if the documents change and the generated file does not, the test fails. It also holds every example to the validator.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { validateSiteSpec } from './site-spec.js'

const docs = (rel: string) => fileURLToPath(new URL(`../../../../docs/release/content/ai-site-spec/${rel}`, import.meta.url))
const generatedFile = fileURLToPath(new URL('./site-spec-material.generated.ts', import.meta.url))

const instructions = readFileSync(docs('instructions.md'), 'utf8')
const examples = readdirSync(docs('examples')).filter((f) => f.endsWith('.json')).sort().map((f) => ({ name: f.replace(/\.json$/, ''), spec: JSON.parse(readFileSync(docs(`examples/${f}`), 'utf8')) as unknown }))

const generated = `// Generated by site-spec-material.test.ts from docs/release/content/ai-site-spec (instructions.md and examples/*.json). Do not edit: change the documents and run
//   UPDATE_SITE_SPEC_SCHEMA=1 pnpm --filter @whoobe-cms/schema test
export const SITE_SPEC_INSTRUCTIONS: string = ${JSON.stringify(instructions)}

export const SITE_SPEC_EXAMPLES: { name: string; spec: unknown }[] = ${JSON.stringify(examples, null, 2)}
`

if (process.env.UPDATE_SITE_SPEC_SCHEMA) writeFileSync(generatedFile, generated)

describe('site spec: instructions and examples', () => {
  it('the generated copy is the one of the documents (drift test)', () => {
    expect(readFileSync(generatedFile, 'utf8')).toBe(generated)
  })

  it('every example is a valid specification', () => {
    expect(examples.length).toBeGreaterThanOrEqual(2)
    for (const e of examples) {
      const r = validateSiteSpec(e.spec)
      expect(r.ok, `${e.name}: ${r.ok ? '' : JSON.stringify(r.issues.slice(0, 3))}`).toBe(true)
    }
  })

  it('the example inside the instructions is valid too', () => {
    const block = instructions.slice(instructions.indexOf('## Example')).match(/```json\n([\s\S]*?)\n```/)
    expect(block).not.toBeNull()
    const r = validateSiteSpec(JSON.parse(block![1]))
    expect(r.ok, r.ok ? '' : JSON.stringify(r.issues.slice(0, 3))).toBe(true)
  })

  it('the instructions state the limits and the kinds that the schema has', async () => {
    const { SITE_SPEC_LIMITS } = await import('./site-spec.js')
    for (const kind of ['container', 'heading', 'text', 'link', 'image', 'form', 'snippet']) expect(instructions).toContain(`\`${kind}\``)
    expect(instructions).toContain(`At most ${SITE_SPEC_LIMITS.maxPages} pages, ${SITE_SPEC_LIMITS.maxSnippets} snippets, ${SITE_SPEC_LIMITS.maxNodesPerPage} elements per page, ${SITE_SPEC_LIMITS.maxNodesPerSnippet} per snippet, ${SITE_SPEC_LIMITS.maxDepth} levels of nesting, ${SITE_SPEC_LIMITS.maxChildren} children`)
    expect(instructions).toContain(`\`heading.text\` ${300} characters, \`link.text\` ${200}, \`text.html\` ${SITE_SPEC_LIMITS.maxTextLength.toLocaleString('en').replace(',', ' ')}`)
  })

  it('the README lists every file of the folder', () => {
    const readme = readFileSync(docs('README.md'), 'utf8')
    expect(readme).toContain('instructions.md')
    for (const e of examples) expect(readme).toContain(`examples/${e.name}.json`)
  })
})
